// Node 7 -- Reasonable Suspicion Testing Determination (suspicion classification producer)
// Reads:  employee_role (node 2), sf_Are_there_any_Signs_or_Symptoms__c (node 6),
//         sf_Signs_Symptoms__c_1..n (node 27, repeatable -- only reached on "Yes")
// Writes: sf_Signs_Symptoms__c (form, ";"-joined picklist values),
//         transforms.testing_classification / testing_summary_html / testing_summary_text

function g(k) { return ZT.getVariableValue(k, ''); }

function escapeHtml(v) {
  return String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function box(title, body, bg, border) {
  return '<div style="border:1px solid ' + border + ';border-radius:10px;background:' + bg + ';padding:10px 12px;margin-top:10px;font-size:14px;line-height:1.45;color:#111827;">'
    + '<div style="font-weight:700;margin-bottom:4px;">' + title + '</div>'
    + '<div>' + body + '</div></div>';
}

// Each press of "+" on node 27 adds sf_Signs_Symptoms__c_<n>; collect them in order, skip repeats.
function collectSigns() {
  const signs = [];
  let i = 1;
  let sign = g('sf_Signs_Symptoms__c_' + i);
  while (sign !== '') {
    if (signs.indexOf(sign) === -1) signs.push(sign);
    i++;
    sign = g('sf_Signs_Symptoms__c_' + i);
  }
  return signs;
}

const DOT_ROLES = ['Pilot', 'Flight Attendant', 'Mechanic', 'Ground Security Coordinator'];

const role = g('employee_role');
const signsAnswer = g('sf_Are_there_any_Signs_or_Symptoms__c');
const signsPresent = signsAnswer === 'Yes';
const signs = signsPresent ? collectSigns() : [];

const isWFH = role === 'Work From Home Employee';
const isDOT = DOT_ROLES.indexOf(role) !== -1;

// No signs or symptoms -> false alarm: log the event, no testing (Chris, 2026-09-24 call).
let classification, title, bodyHtml, bodyText, bg, border;

if (!signsPresent) {
  classification = 'RS_NO_TESTING';
  title = 'Testing Determination -- Testing Not Needed';
  bodyHtml = '<div>No signs or symptoms observed. <strong>Testing is not needed.</strong></div>'
    + '<div>Log the event and send this summary to Delta.</div>';
  bodyText = 'No signs or symptoms observed. Testing is not needed.\nLog the event and send this summary to Delta.';
  bg = '#f9fafb';
  border = '#e5e7eb';
} else if (isWFH) {
  classification = 'RS_WFH_HOTLINE';
  title = 'Testing Determination -- Testing Needed (Work From Home)';
  bodyHtml = '<div>Work-from-home employee. <strong>Do not self-administer.</strong></div>'
    + '<div>Contact Delta on-call via Hotline: <strong>866-217-8222</strong>.</div>';
  bodyText = 'Work-from-home employee. Do not self-administer.\nContact Delta on-call via Hotline: 866-217-8222.';
  bg = '#fef2f2';
  border = '#fecaca';
} else if (isDOT) {
  classification = 'RS_DOT_HOTLINE';
  title = 'Testing Determination -- Testing Needed (DOT: ' + role + ')';
  bodyHtml = '<div>DOT-covered position. <strong>Do not self-administer.</strong></div>'
    + '<div>Contact Delta on-call via Hotline: <strong>866-217-8222</strong> | DOT Account: <strong>80126730</strong>.</div>';
  bodyText = 'DOT-covered position. Do not self-administer.\nContact Delta on-call via Hotline: 866-217-8222 | DOT Account: 80126730.';
  bg = '#fef2f2';
  border = '#fecaca';
} else {
  classification = 'RS_NON_DOT_TESTING';
  title = 'Testing Determination -- Testing Needed (NON-DOT: ' + (role || 'Unspecified') + ')';
  bodyHtml = '<div>Set up <strong>DRUG AND ALCOHOL testing (RS Non-DOT)</strong> | DOT Account: <strong>80126731</strong>.</div>'
    + '<div>Checklist must be completed by <strong>two Delta managers</strong> (preferably one STP-trained).</div>';
  bodyText = 'Set up DRUG AND ALCOHOL testing (RS Non-DOT) | DOT Account: 80126731.\nChecklist must be completed by two Delta managers (preferably one STP-trained).';
  bg = '#eef2ff';
  border = '#c7d2fe';
}

// Summary HTML
let signsHtml = '<em>None recorded</em>';
if (signs.length) {
  signsHtml = '<ul style="margin:0;padding-left:18px;">';
  for (let i = 0; i < signs.length; i++) {
    signsHtml += '<li>' + escapeHtml(signs[i]) + '</li>';
  }
  signsHtml += '</ul>';
}

let html = box(title, bodyHtml, bg, border);
html += box('Are There Signs or Symptoms?', '<strong>' + escapeHtml(signsAnswer || 'Not answered') + '</strong>', '#f9fafb', '#e5e7eb');
if (signsPresent) {
  html += box('Signs &amp; Symptoms Observed',
    signsHtml
    + '<div style="margin-top:6px;color:#6b7280;font-size:13px;">'
    + 'Reminder: signs/symptoms must be present for testing. Custody of drug paraphernalia alone '
    + '(e.g., THC vape pen) does <strong>not</strong> validate testing.</div>',
    '#f9fafb', '#e5e7eb');
}

let text = title + '\n' + bodyText
  + '\n\nAre There Signs or Symptoms?: ' + (signsAnswer || 'Not answered');
if (signsPresent) text += '\nSigns & Symptoms Observed: ' + (signs.length ? signs.join('; ') : 'None recorded');

// Salesforce multi-select picklist format: values separated by ";".
ZT.setFormData('sf_Signs_Symptoms__c', signs.join(';'));
ZT.setTransformData('testing_classification', classification);
ZT.setTransformData('testing_summary_html', html);
ZT.setTransformData('testing_summary_text', text);

