// Unified finalize engine — Delta Post Accident (CR-001 R12/R13)
// Shared by BOTH the accident/damage branch (node 18 producer) and the
// reasonable-suspicion branch (node 7 producer). Normalizes inputs, computes the
// canonical DOT/account-number rule, runs the shared airport-routing tables,
// aggregates notes, and stages the final summary + SF payload.
//
// Inputs expected already captured upstream (node 2, before the branch fork):
//   employee_role, sf_Airport_Code__c, sf_Member_ID_Number__c, sf_Internal_Notes__c
// Inputs from the classification producers (node 18 or node 7):
//   testing_summary_html, testing_summary_text

function g(k) { return ZT.getVariableValue(k, ''); }

// Suspicion-branch detector: node 7 (the RS producer) is the only script that ever
// sets an RS_-prefixed testing_classification; node 18 (accident) uses DOT/NON_DOT_*/
// DEFERRED, and the no-testing path (10->11->12) never sets it at all. Declared early
// since actionRoutingText below depends on it.
const rsClassification = String(transforms.testing_classification || '');
const isSuspicionCase = /^RS_/.test(rsClassification);
// Suspicion case with no signs or symptoms (node 7): logged as a false alarm, no testing.
const isNoTestingSuspicion = rsClassification === 'RS_NO_TESTING';
const eventTypeLabel = isSuspicionCase ? 'Reasonable Suspicion' : 'Post Accident';

function escapeHtml(v) {
  return String(v || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function infoRow(label, value) {
  return '<div style="display:flex;gap:10px;padding:8px 0;border-bottom:1px solid #eef2f7;">'
    + '<div style="width:190px;min-width:190px;font-weight:700;color:#111827;">' + escapeHtml(label) + '</div>'
    + '<div style="flex:1;color:#374151;">' + escapeHtml(value) + '</div></div>';
}

function card(title, body, tone) {
  const bg = tone === 'warning' ? '#fff7ed' : tone === 'action' ? '#fef2f2' : '#eef2ff';
  const border = tone === 'warning' ? '#fed7aa' : tone === 'action' ? '#fecaca' : '#c7d2fe';
  const tc = tone === 'warning' ? '#9a3412' : tone === 'action' ? '#991b1b' : '#3730a3';
  return '<div style="border:1px solid ' + border + ';background:' + bg + ';border-radius:12px;padding:12px;margin-top:10px;">'
    + '<div style="font-weight:800;color:' + tc + ';margin-bottom:4px;">' + escapeHtml(title) + '</div>'
    + '<div style="color:#374151;line-height:1.45;">' + escapeHtml(body) + '</div></div>';
}

// ── Canonical DOT rule (R13) — one rule, both branches ────────────────────────
const DOT_ROLES = ['pilot', 'flight attendant', 'mechanic', 'ground security coordinator'];
const employeeRole = g('employee_role').trim();
const roleNorm = employeeRole.toLowerCase();

const isDotRole = DOT_ROLES.indexOf(roleNorm) !== -1;
const isDotAccident = g('sf_Specimen_Requested__c') === 'Yes'
  || g('sf_Is_the_aircraft_destroyed__c') === 'Yes'
  || g('sf_Are_there_any_fatalities__c') === 'Yes'
  || g('is_manual_dot') === 'true';

const isDot = isDotRole || isDotAccident;
const isWFH = roleNorm === 'work from home employee';
const hotlineRequired = isDot || isWFH;
const callRequired = hotlineRequired && !isNoTestingSuspicion;

const sfAccountNumber = hotlineRequired ? '80126730' : '80126731';
const sfAuthority = isDot ? 'DOT' : 'NDOT';
const RS_AUTHORITY_BY_ROLE = {
  'pilot': 'DOT \u2013 Pilot',
  'flight attendant': 'DOT \u2013 Flight Attendant',
  'mechanic': 'DOT \u2013 Mechanic',
  'ground security coordinator': 'DOT \u2013 Ground Security Coordinator'
};
const rsAuthority = RS_AUTHORITY_BY_ROLE[roleNorm] || 'NDOT';

// "Call Delta STP" messaging now driven by the canonical isDot flag (was node 32's
// narrower pilot/flight-attendant-only substring match). WFH keeps its own hotline
// text; WFH is checked first so an employee flagged both WFH and DOT-accident sees
// the WFH hotline message (Assumption A2 — preserves node 51's existing precedence).
const deltaCallText = isNoTestingSuspicion
  ? 'No -- no signs or symptoms, testing not needed.'
  : isWFH
  ? 'Yes — Call 866-217-8222 for Delta on-call (Work From Home)'
  : isDot
    ? 'Yes — Call 866-217-8222 for Delta STP managers'
    : 'No Delta STP manager call required from employee role.';

const actionRoutingText = isNoTestingSuspicion
  ? 'No signs or symptoms observed. Testing is not needed. Log the event and send this summary to Delta.'
  : isWFH
  ? 'Work-from-home employee. Call 866-217-8222 for Delta on-call. Do not self-administer.'
  : isDot
    ? 'DOT-covered position (' + (employeeRole || 'DOT') + '). Call 866-217-8222 for Delta STP managers. Do not self-administer.'
    : isSuspicionCase
      ? 'NON-DOT. Complete the Reasonable Suspicion checklist with two Delta managers (preferably one STP-trained) when applicable. Account ' + sfAccountNumber + '.'
      : 'NON-DOT. Standard post-accident sample collection procedures apply -- no Reasonable Suspicion checklist required for this accident case. Account ' + sfAccountNumber + '.';

const airportCode = g('sf_Airport_Code__c').trim().toUpperCase();

// ── CR-006 (2026-10-15): supervisor email derived from the OSM number ────────
// Agents enter the Delta OSM number as it appears in SF (e.g. 012345600). The
// supervisor's email is the 6-digit core: drop ONE leading 0 and the two trailing
// 0s -> 123456@delta.com (Chris Le'Doux, Observations 7).
function deriveSupervisorEmail(raw) {
  let d = String(raw || '').replace(/\D/g, '');
  if (d.length > 6 && d.charAt(0) === '0') d = d.substring(1);
  if (d.length > 6 && d.slice(-2) === '00') d = d.substring(0, d.length - 2);
  return d.length === 6 ? d + '@delta.com' : '';
}
const supervisorEmail = deriveSupervisorEmail(g('sf_Member_ID_Number__c'));

// Date of Collection + Number of Donors are written by nodes 29-33 (Connected Objects 503/504),
// not here: the SF package cannot assign strings to Date/Number fields (CR-007, 2026-10-15).
// Event_State__c is Text(2) in SF.
const eventState = g('sf_Event_State__c').trim().toUpperCase();

// ── CR-006: Testing Needed (Yes/No) for Salesforce ───────────────────────────
// No = a no-testing outcome (RS no signs, NON-DOT no-testing, medical deferral)
// or the no-testing path (10->11->12, no producer runs). Yes = everything else,
// including the immediate-DOT shortcut (node 4, no producer, is_manual_dot).
const NO_TESTING_CLASSES = ['RS_NO_TESTING', 'NON_DOT_NO_TESTING', 'DEFERRED'];
const testingNeeded = rsClassification
  ? (NO_TESTING_CLASSES.indexOf(rsClassification) === -1 ? 'Yes' : 'No')
  : (g('is_manual_dot') === 'true' ? 'Yes' : 'No');

const whatHappenedNotes = g('sf_Additional_Notes__c').trim();

// ── Airport routing (shared — was duplicated verbatim in nodes 32 & 51) ───────
const supportedAirports = [
  'ATL','AUS','BNA','BOS','BWI','CLE','CLT','CMH','CVG','DAL','DCA','DEN','DFW','DTW',
  'EWR','FLL','HNL','HOU','IAD','IAH','IND','JAX','JFK','LAS','LAX','LGA','MCI','MCO',
