  + '</div>'
  + '<div style="border:1px solid #eef2f7;border-radius:12px;padding:4px 12px;background:#fbfdff;">'
  + infoRow('Airport Code', airportCode || 'Not answered')
  + infoRow('Employee Role', employeeRole || 'Not answered')
  + infoRow('Account Number', sfAccountNumber)
  + infoRow('Authority Type', sfAuthority)
  + infoRow('Delta STP Call', deltaCallText)
  + infoRow('Testing Needed', testingNeeded)
  + infoRow('Supervisor Email', supervisorEmail || 'Could not derive -- check OSM number')
  + '</div>';

html += callRequired
  ? card('Action Required', actionRoutingText, 'action')
  : isNoTestingSuspicion
    ? card('No Testing Needed', actionRoutingText, 'info')
    : card(isSuspicionCase ? 'NON-DOT Checklist' : 'NON-DOT Instructions', actionRoutingText, 'info');

html += card('Base / City Specifics', baseText, baseNotes.length ? 'warning' : 'info');
html += card('Provider Routing', providerText, providerNotes.length ? 'warning' : 'info');
html += card('Collection Team Notes', teamText, 'info');
if (whatHappenedNotes) html += card('What Happened / Notes (Send to Delta)', whatHappenedNotes, 'info');
html += '</div></div>';

// ── Build final text ───────────────────────────────────────────────────────────
let text = testingText + '\n'
  + 'Sample Collection Instructions\n'
  + 'Airport Code: ' + (airportCode || 'Not answered') + '\n'
  + 'Employee Role: ' + (employeeRole || 'Not answered') + '\n'
  + 'Account Number: ' + sfAccountNumber + '\n'
  + 'Authority Type: ' + sfAuthority + '\n'
  + 'Delta STP Call: ' + deltaCallText + '\n'
  + 'Testing Needed: ' + testingNeeded + '\n'
  + 'Supervisor Email: ' + (supervisorEmail || 'Could not derive -- check OSM number') + '\n'
  + 'Base / City Specifics: ' + baseText + '\n'
  + 'Provider Routing: ' + providerText + '\n'
  + 'Collection Team Notes: ' + teamText + '\n'
  + (whatHappenedNotes ? 'What Happened / Notes (Send to Delta): ' + whatHappenedNotes + '\n' : '');

// ── Default unapplicable accident damage-type fields to "No" (CR-005) ────────
// Chris (Quest) reported these checkboxes arrive blank in Salesforce whenever
// their damage type wasn't the one selected in the damage-type loop (nodes
// 13-17 only ask about ONE damage type per pass -- see node 15). Blank reads
// as "unknown" in SFDC; Quest wants an explicit "No" for every non-applicable
// checkbox on any non-suspicion session (accident/damage branch, the
// immediate-DOT shortcut, and the no-testing path all qualify). Suspicion-
// branch sessions never run the damage-type loop, so these fields are simply
// out of scope there and are left untouched.
const accidentDefaultNoFields = [
  'sf_Aircraft_Ground_Damage_Requires_Maint__c',
  'sf_Aircraft_Out_of_Service__c',
  'sf_Extensive_Prop_Damage_Disrupts_Ops__c',
  'sf_Airport_Property_Structural_Damage__c',
  'sf_Vehicle_Damage__c',
  'sf_Flight_Delays__c',
  'sf_Personal_Injury__c'
];
if (!isSuspicionCase) {
  accidentDefaultNoFields.forEach(function (fieldName) {
    if (g(fieldName) === '') ZT.setFormData(fieldName, 'No');
  });
}

// ── Email-only staging ───────────────────────────────────────────────────────
// The emails carry the testing determination, the call instruction when one is required, and the
// What Happened notes -- not the agent-screen routing cards (NON-DOT instructions, base/city,
// provider routing, collection team notes). Test panel follows the account number; the state
// specimen rule (MN breath alcohol / CA oral fluid) rides next to Specimens Requested.
const TEST_PANEL_BY_ACCOUNT = { '80126731': '65105N', '80126730': '65304N' };
const testPanel = TEST_PANEL_BY_ACCOUNT[sfAccountNumber] || '';
const caPanelNote = caAirports.indexOf(airportCode) !== -1
  ? 'California: oral fluid (Quantisal), account 11348169, test panel 40002N.'
  : '';
let emailHtml = '<div style="font-family:Arial,sans-serif;">' + testingHtml;
if (callRequired) emailHtml += card('Action Required', actionRoutingText, 'action');
else if (isNoTestingSuspicion) emailHtml += card('No Testing Needed', actionRoutingText, 'info');
if (whatHappenedNotes) emailHtml += card('What Happened / Notes', whatHappenedNotes, 'info');
emailHtml += '</div>';

ZT.setFormData('authority_display', isSuspicionCase ? rsAuthority : sfAuthority);
ZT.setFormData('test_panel', testPanel);
ZT.setFormData('ca_panel_note', caPanelNote);
ZT.setFormData('specimen_state_note', baseNotes.join(' '));
ZT.setTransformData('email_determination_html', emailHtml);

// ── Outputs — sf_*__c fields are the SFDC payload, read back out-of-band by the
// Salesforce embed after the session (no in-tree Connected Object; see claude.md).
// Per house rule (Zingtree Builder/MEMORY.md): HTML -> setTransformData only;
// simple string/number/boolean scalars -> setFormData only. (Fixed 2026-07-29 --
// the prior draft dual-wrote everything through both stores via a shared set()
// helper inherited verbatim from the pre-existing node 32/51 scripts; that
// legacy pattern predates this build and isn't the house rule for NEW code.)
ZT.setFormData('sf_Account_Number__c', sfAccountNumber);
ZT.setFormData('sf_Delta_Post_Accident_Authority__c', sfAuthority);
// CR-006 (validated in SF Object Manager 2026-10-15): Delta_Reasonable_Suspicion_Authority__c is a
// restricted picklist of role-specific values ("DOT \u2013 Pilot" etc., en dash) + "NDOT" -- plain "DOT"
// is not a valid value, which is why it never populated. Only written on suspicion sessions.
if (isSuspicionCase) ZT.setFormData('sf_Delta_Reasonable_Suspicion_Authority__c', rsAuthority);
ZT.setFormData('sf_Testing_Needed__c', testingNeeded);
if (eventState) ZT.setFormData('sf_Event_State__c', eventState);
ZT.setFormData('sf_Contact_Email_Address__c', supervisorEmail);
ZT.setFormData('sf_Airport_Code__c', airportCode);
ZT.setFormData('sf_Employee_Role__c', employeeRole);
