// Node 29 -- Stage typed Salesforce fields (CR-007, 2026-10-15)
// The Salesforce managed package writes sf_* form fields to the ES Event Request as strings, which
// Salesforce rejects for Date/Number fields ("Illegal assignment from String to Date") and the
// whole screen's save fails. Node 28 therefore captures these two under non-sf names and this
// script stages them for Connected Objects 503 (Date_of_Collection__c) and 504 (Number_of_Donors__c).
// Inputs:  date_of_collection, number_of_donors (node 28)
// Outputs: date_of_collection_iso, has_collection_date, date_of_collection_invalid,
//          number_of_donors, has_donor_count
function g(k) { return String(ZT.getVariableValue(k, '') || '').trim(); }
function pad2(v) { return ('0' + v).slice(-2); }
function toIsoDate(v) {
  if (!v) return '';
  var m = v.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  var y, mo, d;
  if (m) { y = +m[1]; mo = +m[2]; d = +m[3]; }
  else {
    m = v.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2}|\d{4})$/);
    if (!m) return null;
    mo = +m[1]; d = +m[2]; y = m[3].length === 2 ? 2000 + +m[3] : +m[3];
  }
  if (mo < 1 || mo > 12 || d < 1 || d > 31) return null;
  return y + '-' + pad2(mo) + '-' + pad2(d);
}
var rawDate = g('date_of_collection');
var iso = toIsoDate(rawDate);
ZT.setFormData('date_of_collection_iso', iso || '');
ZT.setFormData('has_collection_date', iso ? 'true' : 'false');
ZT.setFormData('date_of_collection_invalid', iso === null ? 'true' : 'false');
var donors = g('number_of_donors').replace(/[^0-9]/g, '');
ZT.setFormData('number_of_donors', donors);
ZT.setFormData('has_donor_count', donors ? 'true' : 'false');

