// Read the ES Event Request back from Salesforce (Data node 34) and stage the fields that only
// Salesforce holds: call date/time, incident date/time, reason for test, specimens requested,
// collector, time of collection, company. Grades the call first; a failed or missing read leaves
// every value blank and shows a warning on the summary screen so the agent can enter the collector.
// Inputs:  actions.salesforce__get_event_request (records[0])
// Outputs: call_date, call_time, incident_date, incident_time, reason_for_test,
//          specimens_requested, collection_time, test_type, company_name, collector_name_sf,
//          collector_phone_sf, collector_eta_sf, collector_global_id_sf; transforms.sf_event_details_html
let res = actions.salesforce__get_event_request || {};
let meta = res._zt_meta || {};
let code = meta.response ? Number(meta.response.code) : 0;
let rec = (code >= 200 && code < 300 && res.records && res.records.length) ? res.records[0] : null;

function f(k) { return rec && rec[k] !== null && rec[k] !== undefined ? String(rec[k]).trim() : ''; }
function pad2(v) { return ('0' + v).slice(-2); }
function fmtDate(v) {
  let m = String(v || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? m[2] + '/' + m[3] + '/' + m[1] : String(v || '');
}
function fmtTime(v) {
  let m = String(v || '').match(/^(\d{1,2}):(\d{2})/);
  if (!m) return String(v || '');
  let h = Number(m[1]);
  return (h % 12 === 0 ? 12 : h % 12) + ':' + m[2] + (h < 12 ? ' AM' : ' PM');
}
function escapeHtml(v) {
  return String(v || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

let company = rec && rec.Company__r && rec.Company__r.Name ? String(rec.Company__r.Name) : 'Delta Air Lines';
let out = {
  call_date: fmtDate(f('Call_Date__c')),
  call_time: fmtTime(f('Call_Time_Actual__c')),
  incident_date: fmtDate(f('Date_of_Incident__c')),
  incident_time: fmtTime(f('Time_of_Incident_Actual__c')),
  reason_for_test: f('Event_Reason2__c'),
  specimens_requested: f('Type_of_Specimen_Requested__c').replace(/;/g, ', '),
  collection_time: fmtTime(f('Appt_Scheduled_Time_Actual__c')),
  test_type: f('Test_Type__c'),
  company_name: company,
  collector_name_sf: f('Collector_Name__c'),
  collector_phone_sf: f('Collector_Phone__c'),
  collector_eta_sf: f('Collector_ETA__c'),
  collector_global_id_sf: f('GID_Number__c')
};
for (let k in out) ZT.setFormData(k, out[k]);

let rows = [
  ['Call Date', out.call_date], ['Call Time', out.call_time],
  ['Date of Incident', out.incident_date], ['Time of Incident', out.incident_time],
  ['Reason for Test', out.reason_for_test], ['Specimens Requested', out.specimens_requested],
  ['Collector Name', out.collector_name_sf], ['Collector Phone', out.collector_phone_sf],
  ['Collector ETA', out.collector_eta_sf], ['ExamOne Global ID', out.collector_global_id_sf]
];
let html = '<div style="font-family:Arial,sans-serif;max-width:760px;border:1px solid ' + (rec ? '#c7d2fe' : '#fecaca') + ';background:' + (rec ? '#eef2ff' : '#fef2f2') + ';border-radius:12px;padding:12px;margin-bottom:12px;">'
  + '<div style="font-weight:800;color:' + (rec ? '#3730a3' : '#991b1b') + ';margin-bottom:6px;">From Salesforce</div>';
if (!rec) {
  html += '<div style="color:#374151;">Event details could not be read from Salesforce (HTTP ' + escapeHtml(code || 'no response') + '). Enter the collector below; call and incident details will be blank in the emails.</div>';
} else {
  for (let i = 0; i < rows.length; i++) {
    html += '<div style="display:flex;gap:10px;padding:4px 0;"><div style="width:170px;min-width:170px;font-weight:700;color:#111827;">' + rows[i][0] + '</div><div style="color:#374151;">' + escapeHtml(rows[i][1] || 'Not set in Salesforce') + '</div></div>';
  }
  html += '<div style="color:#6b7280;font-size:13px;margin-top:6px;">Collector fields below override Salesforce for the emails. Leave blank to use these values.</div>';
}
html += '</div>';
ZT.setTransformData('sf_event_details_html', html.replace(/\n/g, ''));

