// Stage the email-only values right before the two Email nodes: resolve the collector (agent entry
// on the summary screen wins over Salesforce) and render the questionnaire (every question the agent
// answered, with its answer) for the Incident Summary email.
// Inputs:  collector_*_entry (node 20), collector_*_sf (node 35), node 1/10/6/27 answers,
//          employee_role, transforms.final_records (damage loop)
// Outputs: collector_name, collector_phone, collector_eta, collector_global_id;
//          transforms.questionnaire_html
function g(k) { return String(ZT.getVariableValue(k, '') || '').trim(); }
function escapeHtml(v) {
  return String(v || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

let parts = ['name', 'phone', 'eta', 'global_id'];
for (let p = 0; p < parts.length; p++) {
  ZT.setFormData('collector_' + parts[p], g('collector_' + parts[p] + '_entry') || g('collector_' + parts[p] + '_sf'));
}

let QUESTIONS = [["sf_Specimen_Requested__c", "Is this a major aircraft accident? (Aircraft is unrepairable / totaled / never to fly again)"], ["sf_Is_the_aircraft_destroyed__c", "Is the aircraft destroyed?"], ["sf_Are_there_any_fatalities__c", "Are there any fatalities?"], ["employee_role", "Donor Role"], ["sf_Minor_or_cosmetic_damage__c", "Was the damage to equipment, vehicle, aircraft, or property equivalent to or less than a fingernail scratch (minor / cosmetic only)?"], ["sf_Fault_due_to_mechanical_equipment_fail__c", "Was the employee at fault due to mechanical/equipment failure or other person’s actions? verified by maintenance investigation?"], ["sf_Incident_caused_by_weather__c", "Did weather cause the incident?"], ["sf_Over_32_hours_since_incident__c", "Has it been over 32 hours since the incident occurred?"], ["hours_elapsed", "How many hours has it been since the incident?"], ["sf_Are_there_any_Signs_or_Symptoms__c", "Are There Signs or Symptoms?"], ["sf_Signs_Symptoms__c", "Signs or Symptoms Observed"], ["sf_Additional_Notes__c", "What Happened?"]];
let DAMAGE_QUESTIONS = [["sf_Aircraft_Ground_Damage_Requires_Maint__c", "Was damage to the aircraft caused by equipment or personnel and requires maintenance action?"], ["aircraft_employee_fault", "Was the employee at fault for the aircraft damage?"], ["sf_Aircraft_Out_of_Service__c", "Is the aircraft taken out of service for repairs?"], ["sf_Equip_removed_from_Service__c", "Was the GSE (tugs, carts, pushback tugs, tow bars, loaders, jet bridges, etc.) required to be removed from service?"], ["sf_Equipment_Undergo_Maintenance_Inspection__c", "Did the equipment undergo a maintenance inspection before it could be used again?"], ["sf_Shear_Pin_Damage__c", "Was ONLY the shear pin (in towbar) damaged during pushback?"], ["sf_Vehicle_Damage__c", "Were any vehicles damaged (trucks, cars, high-lift trucks, crew vans, de-icing trucks, buses, etc.)?"], ["sf_Airport_Property_Structural_Damage__c", "Was there airport property/structural damage (hole in wall, leaking fluid, damage to doors, jetways, etc.)?"], ["sf_Extensive_Prop_Damage_Disrupts_Ops__c", "Was the property damage extensive enough to disrupt the operation?"], ["sf_Personal_Injury__c", "Personal Injury or Other Person Injuries"], ["injury_medical_care", "Does the injured employee need medical care (or are they seeking medical attention)?"], ["sf_Flight_Delays__c", "Was there any delay to the flight due to the damage incurred?"], ["sf_Additional_Notes__c", "What Happened?"]];

function row(q, a) {
  return '<tr><td style="padding:6px 8px;border-bottom:1px solid #e5e7eb;font-size:13px;color:#374151;vertical-align:top;">' + escapeHtml(q)
    + '</td><td style="padding:6px 8px;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;font-weight:700;vertical-align:top;width:35%;">' + escapeHtml(a) + '</td></tr>';
}

let records = transforms.final_records || [];
let html = '';
for (let i = 0; i < QUESTIONS.length; i++) {
  if (QUESTIONS[i][0] === 'sf_Additional_Notes__c' && records.length) continue;
  let answer = g(QUESTIONS[i][0]);
  if (QUESTIONS[i][0] === 'sf_Signs_Symptoms__c') answer = answer.split(';').join(', ');
  if (answer) html += row(QUESTIONS[i][1], answer);
}
for (let r = 0; r < records.length; r++) {
  html += row('Damage Type', records[r].damage_type || '');
  for (let j = 0; j < DAMAGE_QUESTIONS.length; j++) {
    let v = String(records[r][DAMAGE_QUESTIONS[j][0]] || '').trim();
    if (v) html += row(DAMAGE_QUESTIONS[j][1], v);
  }
}
html = html
  ? '<table style="width:100%;border-collapse:collapse;">' + html + '</table>'
  : '<div style="font-size:13px;color:#6b7280;">No questionnaire answers recorded.</div>';
ZT.setTransformData('questionnaire_html', html);
